  "lib/src/0_templates/architectures/clean_architecture/skills/clean-arch-auditor/SKILL.md":
      "---\n"
      "name: clean-arch-auditor\n"
      "description: |\n"
      "  Clean Architecture (4層) プロジェクトの構造・依存方向を監査するスキル。\n"
      "  「構造をチェックして」「レイヤー違反がないか見て」「依存方向を確認して」時に使用。\n"
      "---\n"
      "\n"
      "# Clean Architecture 監査スキル\n"
      "\n"
      "## 手順\n"
      "\n"
      "1. `utakata check --json` で不足ファイル・余分なファイル・命名規則違反を確認する\n"
      "2. 違反があれば、該当レイヤーのガイドを `utakata guide show <layer>` で参照してから修正する\n"
      "3. 依存方向を確認する。許可される依存は一方向のみ:\n"
      "   - `4_presentation` → `3_application` → `1_domain`\n"
      "   - `2_infrastructure` → `1_domain`\n"
      "   - `1_domain` はどの層にも依存しない(`dart:io` も禁止)\n"
      "\n"
      "## 違反の典型例\n"
      "\n"
      "- domain 層に `dart:io` / infrastructure の import がある\n"
      "- presentation 層から repository 実装を直接 import している\n"
      "- `exceptions/` 配下のファイル名が親ディレクトリの命名規則に従っていない\n"
      "- feature 直下にレイヤー番号のないディレクトリがある\n"
      "\n"
      "## 制約\n"
      "\n"
      "- 修正提案の前に必ず `utakata check` の実際の出力を根拠にすること\n"
      "- `doc/records/**` は読み取り専用。監査結果の記録が必要なら人間にコマンド実行を提案する\n",
  "lib/src/0_templates/architectures/mvvm/arch_definition.yaml":
      "# アーキテクチャ定義: MVVM (3-layer)\n"
      "#\n"
      "# Model-View-ViewModel パターン。\n"
      "# Flutter の状態管理を ViewModel 層に集約するシンプルなアーキテクチャ。\n"
      "# Clean Architecture より層が少なく、小〜中規模プロジェクト向け。\n"
      "#\n"
      "# 構造以外は別の場所が正:\n"
      "#   - 外部依存(バージョン + 使ってよい層)→ dependencies/*.yaml\n"
      "#   - 読み物(解説・コード例)→ layers/**/GUIDE.md, principles/\n"
      "\n"
      "id: mvvm\n"
      "displayName: \"MVVM (3-layer)\"\n"
      "guides_path: \"principles\"\n"
      "\n"
      "# コアモジュール\n"
      "core_modules:\n"
      "  - id: routing\n"
      "    path: \"lib/core/routing\"\n"
      "    displayName: \"routing/\"\n"
      "  - id: theme\n"
      "    path: \"lib/core/theme\"\n"
      "    displayName: \"theme/\"\n"
      "  - id: di\n"
      "    path: \"lib/core/di\"\n"
      "    displayName: \"di/\"\n"
      "  - id: api\n"
      "    path: \"lib/core/api\"\n"
      "    displayName: \"api/\"\n"
      "\n"
      "# ─── レイヤー定義 ───\n"
      "# MVVM は 3層:\n"
      "#   1_model     : データモデル、リポジトリインターフェース、サービス\n"
      "#   2_viewmodel : 状態管理、ビジネスロジック\n"
      "#   3_view      : UI（Screen / Widget）\n"
      "layers:\n"
      "  - name: 1_model\n"
      "    dirs:\n"
      "      - 1_entities\n"
      "      - 2_repositories\n"
      "      - 3_services\n"
      "      - exceptions\n"
      "\n"
      "  - name: 2_viewmodel\n"
      "    dirs:\n"
      "      - 1_states\n"
      "      - 2_notifiers\n"
      "\n"
      "  - name: 3_view\n"
      "    dirs:\n"
      "      - 1_widgets\n"
      "      - 2_screens\n"
      "\n"
      "# ─── 命名規則 ───\n"
      "naming_rules:\n"
      "  - dir_pattern: \"1_model/1_entities\"\n"
      "    file_pattern: \"^.+_entity\\\\.dart\$\"\n"
      "    description: \"{name}_entity.dart\"\n"
      "\n"
      "  - dir_pattern: \"1_model/2_repositories\"\n"
      "    file_pattern: \"^.+_repository\\\\.dart\$\"\n"
      "    description: \"{name}_repository.dart\"\n"
      "\n"
      "  - dir_pattern: \"1_model/3_services\"\n"
      "    file_pattern: \"^.+_service\\\\.dart\$\"\n"
      "    description: \"{name}_service.dart\"\n"
      "\n"
      "  - dir_pattern: \"1_model/exceptions\"\n"
      "    file_pattern: \"^.+_exception\\\\.dart\$\"\n"
      "    description: \"{name}_exception.dart\"\n"
      "\n"
      "  - dir_pattern: \"2_viewmodel/1_states\"\n"
      "    file_pattern: \"^.+_state\\\\.dart\$\"\n"
      "    description: \"{feature}_state.dart\"\n"
      "\n"
      "  - dir_pattern: \"2_viewmodel/2_notifiers\"\n"
      "    file_pattern: \"^.+_notifier\\\\.dart\$\"\n"
      "    description: \"{feature}_notifier.dart\"\n"
      "\n"
      "  - dir_pattern: \"3_view/1_widgets\"\n"
      "    file_pattern: \"^.+_widget\\\\.dart\$\"\n"
      "    description: \"{name}_widget.dart\"\n"
      "\n"
      "  - dir_pattern: \"3_view/2_screens\"\n"
      "    file_pattern: \"^.+_screen\\\\.dart\$\"\n"
      "    description: \"{feature}_screen.dart\"\n"
      "\n"
      "# ─── import 監査規則 (`utakata imports` が使用) ───\n"
      "# 書式は clean_architecture と同じ(layers = 層間依存グラフ、dirs = 細則)。\n"
      "import_rules:\n"
      "  exclude:\n"
      "    - \"**.g.dart\"\n"
      "    - \"**.freezed.dart\"\n"
      "\n"
      "  layers:\n"
      "    1_model: []                        # 何にも依存しない\n"
      "    2_viewmodel: [1_model]\n"
      "    3_view: [1_model, 2_viewmodel]\n"
      "\n"
      "  dirs:\n"
      "    - dir_pattern: \"1_model/1_entities\"\n"
      "      allow: [\"1_model/exceptions\"]\n"
      "    - dir_pattern: \"1_model/exceptions\"\n"
      "      allow: [\"1_model/1_entities\"]\n"
      "    # 状態クラスは純粋(エンティティ以外を見ない)\n"
      "    - dir_pattern: \"2_viewmodel/1_states\"\n"
      "      allow: [\"1_model/1_entities\"]\n"
      "    # ウィジェット部品は表示専念(状態は screens が watch して流し込む)\n"
      "    - dir_pattern: \"3_view/1_widgets\"\n"
      "      allow: [\"1_model/1_entities\"]\n"
      "\n"
      "# 層ごとの要点(オフライン時の guide show 用の要約。本文は layers/**/GUIDE.md)\n"
      "guides:\n"
      "  - layer_path: \"1_model/1_entities\"\n"
      "    title: \"Entity Layer — エンティティ層\"\n"
      "    do:\n"
      "      - \"ビジネスオブジェクトの定義(freezed でイミュータブルに)\"\n"
      "      - \"純粋な Dart コード(外部ライブラリに依存しない)\"\n"
      "    dont:\n"
      "      - \"UI・状態管理・永続化への依存\"\n"
      "\n"
      "  - layer_path: \"1_model/2_repositories\"\n"
      "    title: \"Repository Layer — リポジトリ層\"\n"
      "    do:\n"
      "      - \"データアクセスの抽象化(abstract interface class)\"\n"
      "      - \"実装クラスは同ディレクトリに配置({name}_repository_impl.dart)\"\n"
      "    dont:\n"
      "      - \"UI・状態管理ライブラリへの依存\"\n"
      "\n"
      "  - layer_path: \"1_model/3_services\"\n"
      "    title: \"Service Layer — サービス層\"\n"
      "    do:\n"
      "      - \"ビジネスロジックの集約(複数リポジトリの協調・業務処理)\"\n"
      "    dont:\n"
      "      - \"UI ロジックの混入・状態管理ライブラリへの依存\"\n"
      "\n"
      "  - layer_path: \"1_model/exceptions\"\n"
      "    title: \"Model Exceptions Layer — 例外層\"\n"
      "    do:\n"
      "      - \"ドメイン固有エラーの型安全な定義\"\n"
      "    dont:\n"
      "      - \"インフラ層エラー(HTTP/SQL)の漏洩\"\n"
      "\n"
      "  - layer_path: \"2_viewmodel/1_states\"\n"
      "    title: \"ViewModel State Layer — 状態定義層\"\n"
      "    do:\n"
      "      - \"UI 状態の不変オブジェクト定義(@freezed)\"\n"
      "    dont:\n"
      "      - \"ミュータブルな状態表現・Flutter UI への依存\"\n"
      "\n"
      "  - layer_path: \"2_viewmodel/2_notifiers\"\n"
      "    title: \"ViewModel Notifier Layer — ノティファイア層\"\n"
      "    do:\n"
      "      - \"ユーザーイベントを受けて Service を呼び出し State を更新\"\n"
      "    dont:\n"
      "      - \"ビジネスルールの直接記述(Service へ委譲)・Flutter UI への依存\"\n"
      "\n"
      "  - layer_path: \"3_view/1_widgets\"\n"
      "    title: \"View Widget Layer — ウィジェット層\"\n"
      "    do:\n"
      "      - \"再利用可能な UI 部品の定義(データは引数で受け取る)\"\n"
      "    dont:\n"
      "      - \"Riverpod への直接依存・ビジネスロジックの混入\"\n"
      "\n"
      "  - layer_path: \"3_view/2_screens\"\n"
      "    title: \"View Screen Layer — 画面層\"\n"
      "    do:\n"
      "      - \"画面レイアウトの構築と Notifier の状態 watch\"\n"
      "    dont:\n"
      "      - \"ビジネスロジック記述・Repository/Service の直接呼び出し\"\n",
  "lib/src/0_templates/architectures/mvvm/dependencies/core_stack.yaml":
      "# コアスタック: 外部依存の正(バージョン + 配置宣言)\n"
